package services.clientproxy;

import data.*;
import org.eclipse.jetty.util.BlockingArrayQueue;
import services.INO.DynamoDBPersistenceManagerForClaims;

import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.LinkedBlockingDeque;
import java.util.concurrent.LinkedBlockingQueue;

// This is used to store the session key generated by the key agreement . This allows same client to come in again and execute a new key agreement.


public class NonceCache {


   Queue<Nonce> nonceList = new LinkedBlockingQueue<>();


    public void put(Nonces nonces)
    {
        nonceList.addAll(nonces.getNonces());
    }

    public Nonce get()
    {
        if (nonceList.isEmpty())  // race condition here for multiple checkers - will be fixed if water mark based future is added.
        {
            INOConnector connector =  INOConnector.buildINOConnector();
            Nonces nonces = connector.getNonces();
            put(nonces);

        }

        return nonceList.remove();
    }

}
